func HasProjectSubscribersWith(preds ...predicate.ProjectSubscriber) predicate.Project {
	return predicate.Project(func(s *sql.Selector) {
		step := newProjectSubscribersStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasProjectTeams applies the HasEdge predicate on the "project_teams" edge.
func HasProjectTeams() predicate.Project {
	return predicate.Project(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, true, ProjectTeamsTable, ProjectTeamsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasProjectTeamsWith applies the HasEdge predicate on the "project_teams" edge with a given conditions (other predicates).
func HasProjectTeamsWith(preds ...predicate.ProjectTeam) predicate.Project {
	return predicate.Project(func(s *sql.Selector) {
		step := newProjectTeamsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Project) predicate.Project {
	return predicate.Project(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Project) predicate.Project {
	return predicate.Project(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Project) predicate.Project {
	return predicate.Project(sql.NotPredicates(p))
}
